import{_ as p,c as e,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"豐","description":"高島易斷 - 豐","frontmatter":{"title":"豐","description":"高島易斷 - 豐"},"headers":[],"relativePath":"classics/takashima/055.md","filePath":"classics/takashima/055.md"}'),i={name:"classics/takashima/055.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="豐" tabindex="-1">豐 <a class="header-anchor" href="#豐" aria-label="Permalink to “豐”">​</a></h1><h2 id="豐-1" tabindex="-1">豐 <a class="header-anchor" href="#豐-1" aria-label="Permalink to “豐”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>豐：亨，王假之。勿憂，宜日中。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《正義》曰：“財多德大，故謂之豐。”財多則足以濟世，德大則足以容人，事無窒礙，故“亨”。“王”指殷王，“假”，謂感假。《萃》《渙》之假，言殷王假廟也，《豐》之假，期紂之能假也。期能假夫《豐》亨之道，自足以統馭萬國，照臨下土，如日之正中，光明遍被，故曰“勿憂”。《離》為日，日中則明愈大，故曰“宜日中”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>雷電皆至，豐。君子以折獄致刑。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>此卦《震》為雷，《離》為電，雷電相合，威勢盛大，電主明，雷主威，《象》曰“雷電皆至”，有威明兼備之象焉。明以“折獄”，則獄得其情，斯天下無遁情矣；威以“致刑”，則刑當其罪，斯天下無遺奸矣。君子見《豐》之象，推威嚴光明之德，洞悉奸偽，以明運威，故能察亦能決；以威濟明，故無枉亦無私。天之《震》也，雷聲之作，電火在先，此其象也。得《離》之明者，為《噬嗑》、《賁》、《豐》、《旅》四卦，《大象》俱有用刑之義。《噬嗑》明在上，象君子在上，故為“明罰敕法”；《豐》明在下，象君子在下，故曰“折獄致刑”。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：氣運旺盛，但當豐不忘歉，斯豐可長保矣。</p><p>○　問營商：財利豐盛，但須公平謹守，否則恐有訟獄牽連。</p><p>○　問功名：雷電有威名發達之象，宜任刑官。</p><p>○　問戰徵：雷電皆至，見兵威顯赫，聲勢遠揚，攻戰必克。</p><p>○　問婚姻：世稱雷為公，電為母，是天合也。</p><p>○　問家宅：宅向東南，財氣頗豐。</p><p>○　問疾病：是肝火上升之症，宜洩肝瀉火之劑，尤宜靜養。</p><p>○　問失物：皆速追究，可得。</p><p>○　問行人：防有訟事糾纏。</p><p>○　問六甲：單月生男，雙月生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>“配”鄭作妃，卦體《震》上《離》下，初本《震》爻，為諸侯，初與四應，故以四為“配主”。初九爻辰在子，九四爻辰在午，君南面，臣北面，初以修禮朝四，四以匹敵厚恩遇之，雖留十日，不以為咎。正以十日者，朝聘之禮，自行聘至問大夫，才五六日，即事畢請歸，鄭注謂主國留之，饗食燕獻，無日數，盡殷勤也。主雖綢繆，而客行淹久，樂不可言。旬以內，尚不逾節，故“無咎”。“往有尚”者，其往或因助祭而行朝聘，或因入朝而遇助祭，留之經旬，神人歡洽，故為可尚。然以旬為限，過則非常。《象傳》謂過則災生，蓋凜凜於日中之戒，示以盈滿為懼也。或以旬始為星名，《史記·天官書》，“旬始出於北斗旁，狀如雄雞”，二爻曰“鬥”，三爻曰“沫”，鬥沫皆星名，言其蔽明也。初以旬始為星，爻象相同，義亦可取。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：得其相助，可有十年好運。</p><p>○　問營商：當有巧當貨物可售，旬日之內，即可獲利，過旬則不利。</p><p>○　問功名：“邂逅相遇，適我願兮”，即日當有佳報。</p><p>○　問戰徵：兩敵相遇，當速進兵，十日外，恐有敗象。</p><p>○　問婚姻：姻緣相當，即日可成，遲則不諧。</p><p>○　問疾病：得遇良醫，旬日可愈，遲久不治。</p><p>○　問訟事：得遇良吏，即可斷結，遲緩不了，恐有外禍。</p><p>○　問失物：宜速尋。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治三十一年，佔英法兩國交際，筮得《豐》之《小過》。</p><p>斷曰：《豐》者，雷電相遇，百物豐饒之卦，以國家交際擬之，是兩雄並峙，有各不相下之勢。今佔英法兩國交際，得此初爻，初與四應，當以初爻屬英，四爻屬法。爻象內外相應，就兩國外勢觀之，叵相和好，而實則兩陽相軋，各挾猜疑，勢必隱相侵奪。何則？內《離》明，外《震》動，明者多謀，動者多勇，各為其國，亦各用其長，明與勇遇，適足相敵，故曰“遇其配主”。英善謀略，是明也，法長雄武，是勇也，“旬”，均也，謂其勢力相均也。由此而更進焉，明者不自恃其明，且進而明其德，勇者不自恃其勇，且進而勇於義，斯豐者可長保其豐矣，故曰“往有尚”也。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>六二居《離》之中，為明之主，日中之象也。“蔀”，虞謂日蔽雲中，王弼謂蔀，覆，暖障光明之物。鄭作菩，《說文》，“菩，草也”；《廣韻》“蔀，草名”。《震》為草，故取象於草。《離》夏之時，草木蒙密，故曰“豐其蔀”。按諸說取象雖不同，而為蔽明則一也。“鬥”者星名，《春秋·運鬥樞》曰：北斗七星，第一至第四為魁，第五至第七為杓，合為鬥。九四《震》動，斗柄之象，斗柄左旋，日體右轉。日中非見鬥之時，“日中見鬥”，則有鬥無日矣。喻言殷紂昏亂，奸臣弄權，儼如晝日掩光，而宵鬥騰輝也，故曰“日中見鬥”。當群奸蔽惑，雖周文之聖，猶不免羑里之囚，故曰“往得疑疾”。“有孚”者，即《彖》所云“王假”也，文以忠貞服事，至誠相假，是以紂志可回，蔽障開而疑疾自去矣，故“有孚發若”，轉兇而為吉也。《象傳》曰“信以發志”，為言後世人臣，忠而被讒者，能以積誠感主，無不可假也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：能以蒙難艱貞，自得逢凶化吉。</p><p>○　問營商：見識不明，渾如白晝昏暗，不能辦事，致生疑忌。當以至誠待人，得人扶助，方可獲利。</p><p>○　問功名：始兇終吉。</p><p>○　問戰徵：屯軍於豐林茂草之間，伏藏不發，往則恐有不利；必待敵兵內應，一發必得大勝。吉。</p><p>○　問婚姻：始疑終諧。</p><p>○　問家宅：此宅花木太盛，日光被掩，致窗牖失明，必須開豁明亮，方吉。</p><p>○　問疾病：是胸襟不明，積疑成疾，宜以婉言開導，疑竇一開，病體自愈。</p><p>○　問失物：被塵汙所掩，宜撥開蕪草，可尋得之，或在斗升之間。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治三十一年，佔自由黨氣運，筮得《豐》之《大壯》。</p><p>斷曰：爻辭曰“日中見鬥”，日陽象，鬥為星，星陰象，“豐其蔀”，蔀草也，草亦陰象。日陽為君，星為臣，草則庶民也，白晝見鬥，是陰蔽明，臣蔽君也。今佔自由黨氣運，得《豐》二爻，自由黨者，本是庶民之私議，欲以上干政府也，其議皆出自草莽之徒，故謂之“豐其蔀”。以下犯上，即以陰掩陽，猶如妖星而犯日也，故謂之“日中見鬥”。自由黨魁曰星亨，可謂明證矣。星氏論說狂妄，幹世疑忌，人多疾惡，故曰“往得疑疾”。自由黨如能翻然悔悟，不以勢力相凌，而以貞誠相感，斯發言盈廷，鹹得順從也，故曰“有孚發若，吉”。自由黨於十二議會，以反抗政府，致於解散，後當十三議會，星氏有所悔悟，遂順從政府之議，得以無咎。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>毛西河引劉熙雲，“沛者，水草相生之名”，《公羊傳》“草棘曰沛”是也。“豐其沛”，喻言紂朝，群奸在下，如水草叢生，蒙密而蔽明也。三居內外之間，得《巽》氣，《巽》之剛爻為木，柔爻為草，故取沛為水草。“沫”，鄭作昧，服虔雲“日中而昏”是也。《王莽傳》“地皇元年，二月壬申，日正黥，莽惡之，下書曰：日中見昧，陰薄陽，黑氣為災”，即引《易》此文為證。九家《易》雲：沫，斗杓後小星，即輔星也。按輔星在鬥第六星左；《漢書·翟方進傳》，輔沉沒，張晏曰，輔沉沒不見，則天下之兵銷，是輔見則有兵禍。二說為昏為星，所據不同，要皆為周興殷亡之兆。“折其右肱”者，臣以君為元首，君以臣為股肱，文為西伯，故曰“右肱”，紂聽讒言，囚文於羑里，是“折其右肱”也。然當時雖三分有二，文能篤敬止之節，終身事紂，故右肱雖折而無咎。《傳》曰“不可大事”，三居《離》之極，謂人心既離，天下大事，其已去矣。《傳》又曰“終不可用”，三與上相應，上處《震》之極，為卦之終，上爻曰“闃其無人”，紂之所以為匹夫，故曰“終不可用”也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：運途顛倒，明明白晝，渾如黑夜，防有災禍。幸一時身命，尚無恙也。</p><p>○　問戰徵：“沛”或作旆，謂幡旆飄揚，率軍前進，防風雲有變，卒時昏暗，右軍有失。</p><p>○　問營商：防貨價漲落不測，致被耗折。</p><p>○　問功名：終不可用。</p><p>○　問疾病：防右肱有損。</p><p>○　問家宅：田園荒蕪，水草從生，右廡已傾，暫居而已，終不可用也。</p><p>○　問六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某來，為加入某會社，請佔會社之吉凶。筮得《豐》之《震》。</p><p>斷曰：三爻處《震》《離》之間，《震》為草，《離》為光，曰“豐其沛，日中見沫”，象為《震》草蒙密，以致日色無光。以會社言，必是社中小人眾多，反令君子無權，蓋以草喻小人，播弄其間，卒令白晝昏黑，不見天日，即所謂日中而昏也。“折其右肱”者，社中用事之友，即為社中之手足也，手之動用，全在右肱，折者，執而去之也，謂去其社中弄權之尤者，斯會社可無咎矣。爻象如此，勸君以不入為可。友人聞之，因此中止。後會社未幾果閉，友人於是感《易》佔之妙也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四居外卦之始，為動之主，其爻象與二同，四之蔀，猶二之蔀也，四之鬥，猶二之鬥也。但二以陰居陰，《離》日被掩，四則陽剛發動，王心感假，障蔽開而疑疾消矣。“夷主”之遇，即《彖》所云“王假”也。二以疑疾而囚，四以遇主得釋，遇則吉矣，故曰“吉”。《彖》曰“王”，文所稱也；爻曰“夷主”，周公據其實而夷之也。《豐》沛見鬥，《傳》獨於四釋之，邪之害正，其蔽始於近習，故曰“位不當”；陰之掩陽，其災見於白晝，故曰“幽不明”。《震》為行，行得所遇，故曰“吉行”。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：曩時被人矇蔽，今能翻然改作，得好際遇，可以獲吉。</p><p>○　問戰徵：兵入幽谷，不知去路，不見天日，幸遇嚮導，得以前行也。</p><p>○　問營商：前因貨物，真贗混雜，難以銷售，今始得遇受主，方可獲利。</p><p>○　問功名：得此絕好際遇，名可立就，吉。</p><p>○　問婚姻：良緣巧遇，吉。</p><p>○　問家宅：此宅苦於地位不當，幽暗不明，得遇其人，動作一新，則吉。</p><p>○　問疾病：病在目中生翳，所視失明，得良醫，病可治也。</p><p>○　問六甲：生男。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>豪家支配人某來，請佔氣運，筮得《豐》之《明夷》。</p><p>斷曰：“豐其蔀，言草之盛也；“日中見鬥”，鬥而晝見，是晝晦也，其害皆足以蔽明。四以陽居陰，爻象是陽為陰所蔽，幸四入《震》，為動之主，一動則撥開雲霧，得以重見天日，以得“遇其夷主”。今足下問氣運，得此爻象，知足下曩時必為人所抑制，不得自明，今幸得遇逢其主，可以謀事。但此主素性昏庸，故稱曰“夷主”，惟足下誠實素著，得以信任無疑。《傳》曰“吉行”，可以獲吉矣。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五居外卦之中，五與二應，二言“往”，五言“來”，蓋五視二為來也。“章”，美也；“慶”，賞賜也；“譽”，聲譽也。二既得以“往”而“有孚”，五乃因其“來”而“有慶”，蓋隱指文獻文馬，紂賜弓矢之事也，慶出於紂，譽歸於文。豐在是，吉亦在是焉，所謂一人有慶，兆民賴之。二之慶，亦五之慶，故二五之吉同也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：盛運大來，實至名歸，吉莫大焉。</p><p>○　問營商：貨物往來，無不獲利，更可得名。</p><p>○　問功名：得膺恩賞，名利兼全，大吉。</p><p>○　問婚姻：天合良緣，門楣既顯，嫁資亦豐，吉。</p><p>○　問戰徵：可不戰而成功也，奏凱而還，得邀封賞，吉。</p><p>○　問家宅：必是旌表名門，吉。</p><p>○　問疾病：有名醫自來，即可全愈。</p><p>○　問訟事：訟了，且可得賞。</p><p>○　問行人：即日可歸，且有喜事。</p><p>○　問失物：不尋自來。</p><p>○　問秋收：大有豐年。</p><p>○　問謀財：不求自來。</p><p>○　問六甲：生男，主貴。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>親友某富翁來，請佔氣運，筮得《豐》之《革》。</p><p>斷曰：卦名曰《豐》，必是豐富之家；五爻居尊，為一家之主也。爻辭曰“章”，曰“慶”，曰“譽”，曰“吉”，皆全美之象，佔者得此，氣運之盛，不待言矣。但全卦論之，有《離》明被蔽之象，必是家臣弄權，家主被惑，以致善惡不分，百事顛倒。惟二爻為正直可靠，五能聽從二爻之言，知二之美而嘉納之，賞賜之，二之慶，即五之慶，吉莫大焉。足下於家臣中，宜慎擇其人，去邪任賢，斯家道日隆，身運日旺。爻象如此，吉與不吉，即在轉移間也。</p><p>岩手縣閉伊郡田老村商人落合總兵衛者，餘之舊交也，雖其人已故，而音問不絕。本年六月，傳聞該地海嘯，村民死亡靡有孑遺，探問未得復報，心深憂之，乃為一筮，得《豐》之《革》。</p><p>斷曰：“豐者，大也”，海嘯者，災害之大者也。爻辭曰“來章，有慶譽，吉”，料渠一家之中，必有幸脫此災害者，近日當有來報也。後確知該村當時被災，全村漂沒，落合氏家，惟次男總三郎，四男兵吉，以先時趨赴鄰村，得以免禍雲。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“豐其屋”者，自高也，“蔀其家”者，自蔽也。豐大其屋，又障蔽其家，亦有“行其庭，不見其人”之象也。上六重陰，居卦之極，是動極成憊，明極生昏，豐極致衰，極其甚則宗社傾覆，宮室空虛，故曰“窺其戶，闃其無人”。“闃”即無人之狀。幹令升以上爻為說紂之亡，為獨得其旨焉。上為宗廟，“三歲不覿”，是必三歲不祀也。《書》曰：自成湯至於帝乙，罔不明德恤祀，至紂不肯事上帝，棄厥先神祗不祀，故廟中虛曠，“三歲不覿”也。紂惟深藏於瑤臺璇室，以自娛樂，所謂七世之朝，可以觀德者，未幾而為豐草矣，故曰兇也。《傳》所釋“天際翔也”，“際”或作降，“翔”鄭王作祥，謂天降祥，祥，變異之通稱。又所釋“自藏也”，“藏”諸家作戕，王作殘，鄭作傷，皆謂國滅而自亡也。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：有屋無人，大凶之象。</p><p>○　問戰徵：營壘空虛，敗亡之象。</p><p>○　問營商：貨物空存，無人經理，兇。</p><p>○　問功名：身既不保，名於何有？</p><p>○　問婚姻：兇。</p><p>○　問家宅：田園雖富，必是破落之戶，人煙稀少，兇。</p><p>○　問疾病：命不久矣，兇。</p><p>○　問行人：歸聚無期。</p><p>○　問六甲：生男，防不育。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治十五年某月，予因事至橫濱洋銀取引所，晤西村氏等三人，謂予曰：今以大藏省增稅過重，願求減輕，未知政府許否？請一筮決之。筮得《豐》之《離》。</p><p>斷曰：“豐者，大也”，盛也，當洋銀取引所之盛大，日出納數十萬金，其商況之盛，全國罕見，是為“豐其屋，蔀其家”之象也。然取引所出納雖屬豐盛，恐就其內而窺之，亦有所不足矣。至所云願請減稅者，亦恐有其議，未必有其人也，即所謂“闃其無人”也。謂即使請減有人，恐遲之三歲，政府亦未必見許也，故曰“三歲不覿，兇”。於是三氏互相驚視，無語可答。至翌日，該店果然閉歇。</p>',114)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
